entries[186421] = { ["name"] = "Forbidden Necromantic Tome", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+47 Intellect\nEquip: Your damaging spells have a chance to increase your Critical Strike by 48 for 15 sec, stacking up to 3 times.\nUse: Raise the remains of a fallen ally as a skeletal warrior for 30 sec. (10 Min Cooldown)\nSell Price:" }
entries[186422] = { ["name"] = "Tome of Monstrous Constructions", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 Intellect\nUse: Study the tome, learning the weakness of your targeted enemy. Your damaging abilities have a very high chance to deal 229 additional Shadow damage to your studied foe.\n\nStudying a new enemy removes the benefit of any prior studies. (1 Min Cooldown)\nSell Price:" }
entries[186423] = { ["name"] = "Titanic Ocular Gland", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 [Agility or Strength or Intellect]\nEquip: While your health is above 50% you are judged Worthy, increasing your highest secondary stat by 73 . While your health is below 50% you are judged Unworthy, decreasing your highest secondary stat by 73 .\n\"A price paid long ago in exchange for knowledge and power.\"\nSell Price:" }
entries[186424] = { ["name"] = "Shard of Annhylde's Aegis", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 [Agility or Strength]\nUse: Call upon Annhylde's Aegis for protection, reducing damage you take from enemies in front of you by 2015 for 8 sec.\n\nIf the Aegis absorbs at least 7052 damage, it becomes overcharged and will expel coalesced power, dealing 1123 Holy damage to all enemies in front of you as it expires. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[186425] = { ["name"] = "Scrawled Word of Recall", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 Intellect\nUse: Reduce the remaining cooldown of an appropriate healing spell by 4 sec.\n\nValid only for healer specializations. (1 Min Cooldown)\nSell Price:" }
entries[186427] = { ["name"] = "Whispering Shard of Power", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 Strength\nEquip: A voice whispers to you, periodically compelling you to follow its instructions. If you comply, you will be rewarded with 210 of your highest secondary stat for 20 sec.\nSell Price:" }
entries[186428] = { ["name"] = "Shadowed Orb of Torment", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 Intellect\nUse: Gaze into the orb, suffering ( 1263 * 4) Shadow damage over 2 sec to increase your Mastery by 301 for up to 40 sec. The longer you gaze, the more tormented and insightful you become. (2 Min Cooldown)\nSell Price:" }
entries[186429] = { ["name"] = "Decanter of Endless Howling", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 63 Critical Strike\nEquip: Your critical hits have a chance to increase your Strength or Agility by 162 for 15 sec. If you are below 50% health when this occurs, you also heal for ( 525 * 4) over 6 sec.\nSell Price:" }
entries[186430] = { ["name"] = "Tormented Rack Fragment", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 [Agility or Strength]\nEquip: Your damaging spells and abilities have a chance to deal an additional [source value] Shadow damage over 15 sec.\n\nIf a target dies while affected by the Tormentor's Rack Fragment, it leaves a Shredded Soul behind which you can collect to gain 19 Critical Strike for 20 sec.\nSell Price:", ["unresolvedValues"] = true }
entries[186431] = { ["name"] = "Ebonsoul Vise", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 Intellect\nUse: Curse an enemy, dealing 307 Shadow damage every 2 sec for 12 sec. Duration increases by up to 100% based on their missing health. (1 Min 30 Sec Cooldown) (1 Min, 30 Sec Cooldown)\nEquip: If a target dies while affected by the Ebonsoul Vise, it leaves a Shredded Soul behind which you can collect to gain 19 Critical Strike for 20 sec.\nSell Price:" }
entries[186432] = { ["name"] = "Salvaged Fusion Amplifier", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 [Agility or Strength]\nUse: Empower your weapons for 20 sec, causing your attacks to have a very high chance to deal 507 Arcane damage. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[186433] = { ["name"] = "Reactive Defense Matrix", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 [Agility or Strength]\nEquip: Taking damage has a chance to trigger your Reactive Defense Matrix, which reflects the next 2293 damage back at your attacker.\n\nReactive Defense Matrix triggers automatically when your health drops below 20% health. This effect cannot occur more than once per 30 sec.\nSell Price:" }
entries[186434] = { ["name"] = "Weave of Warped Fates", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 [Agility or Strength]\nEquip: If you are killed by no more than 16413 damage, the Weave of Warped Fates will unwind your fate, returning yourself to life and healing for [ 16549 * (1 + Versatility)].\n\nThis effect can only occur once every 8 min.\nSell Price:" }
entries[186435] = { ["name"] = "Carved Ivory Keepsake", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+42 Intellect\nEquip: You have a chance to foresee damage taken by your allies, healing them instantly for 499 when they are injured.\nSell Price:" }
entries[186436] = { ["name"] = "Resonant Silver Bell", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+47 Intellect\nEquip: When you heal an ally who is below 50% health, a Spectral Feline will infuse them for an additional 2839 healing. The Feline will reconstitute itself after 30 sec.\nSell Price:" }
entries[186437] = { ["name"] = "Relic of the Frozen Wastes", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+47 Agility\nEquip: Your attacks have a high chance to deal 73 Frost damage and apply Frozen Heart to the enemy.\nUse: Call a Nerubian to ambush an enemy, impaling them for 2726 Physical damage. Enemies in the Nerubian's path who are affected by your Frozen Heart suffer 229 Frost damage. (1 Min Cooldown)\nSell Price:" }
entries[186438] = { ["name"] = "Old Warrior's Soul", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+47 Strength\nEquip: While in combat your rage builds, increasing your Haste by 25 every 20 sec, stacking up to 5 times.\nEquip: When a nearby ally's health drops below 50%, sacrifice 1177 of your health to heal them for the same amount. May only occur every 1 min.\nSell Price:" }
entries[186439] = { ["name"] = "Dark Ranger's Quiver", ["text"] = "Binds when picked up\nBack\n30 Armor\n+28 Agility\n+42 Stamina\n+ 37 Critical Strike\n+ 19 Haste\nClasses: Hunter\nEquip: Every 10 shots, trigger Withering Fire, striking up to 5 enemies in front of you for 156 Shadow damage.\nSell Price:" }
