entries[186470] = { ["name"] = "Recipe: Crafter's Mark of the Chained Isle", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft an Optional Reagent that sets the required level to 60, item level to 230, and makes the item Unique Equipped.\n\nUsable with Shadowlands recipes for Rare (blue) armor and accessories.\nRequires Tier 4 research level with The Archivists' Codex.\n\"Teaches you how to craft a Crafter's Mark of the Chained Isle.\"" }
