entries[186476] = { ["name"] = "Sinfall Gravewing", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"With anima once again flowing in Sinfall, the Stonewright has been able to infuse these Stoneborn, making them valuable allies in the battles to come.\"\nCovenant:\nVenthyr\nZone:\nRevendreth" }
entries[186477] = { ["name"] = "Pale Gravewing", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Exalted with Death's Advance and the completion of the assault meta achievement \"On the Offensive.\"\n\n\"Gravewings know no fear and are nearly indestructible -- perfect for an assault on the Maw.\"\nCovenant:\nVenthyr\nVendor:\nDuchess Mynx\nZone:\nKorthia\nCost:\n1000\nAchievement:\nOn the Offensive" }
entries[186478] = { ["name"] = "Obsidian Gravewing", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown 70\n\n\"In the darkened skies of Revendreth, you cannot see these creatures coming until it is too late.\"\nCovenant:\nVenthyr\nVendor:\nChachi the Artiste\nZone:\nRevendreth\nCost:\n7500" }
entries[186479] = { ["name"] = "Mastercraft Gravewing", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Handcrafted by the Stonewright herself, this mastefully crafted stoneborn is entrusted only to those she deems worthy.\"\nCovenant:\nVenthyr\nDrop:\nStygian Stonecrusher\nZone:\nKorthia" }
entries[186480] = { ["name"] = "Battle-Hardened Aquilon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Exalted with Death's Advance and the completion of the assault meta achievement \"On the Offensive.\"\n\n\"The aquilon can be a valuable ally in combat, with capabilities exceeding those of the phalynx.\"\nCovenant:\nKyrian\nVendor:\nDuchess Mynx\nZone:\nKorthia\nCost:\n1000\nAchievement:\nOn the Offensive" }
