entries[186485] = { ["name"] = "Ascendant's Aquilon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown 70\n\n\"The aquilon can rapidly transport aspirants, stewards, and even ascended to a location. Hey, sometimes your wings get tired.\"\nCovenant:\nKyrian\nVendor:\nAdjutant Galos\nZone:\nBastion\nCost:\n7500" }
entries[186486] = { ["name"] = "Korthian Herbs", ["text"] = "Quest Item\nUnique (12)\n\"A bundle of Korthian Herbs. They might make for a good tea. You're not entirely certain though.\"" }
entries[186487] = { ["name"] = "Maldraxxian Corpsefly Harness", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Corpseflies were once found throughout Maldraxxus, but many died out in the absence of anima. With anima flowing once again, they swarm.\"\nCovenant:\nNecrolord\nZone:\nMaldraxxus" }
entries[186488] = { ["name"] = "Regal Corpsefly Harness", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown 70\n\n\"Only the forces of Maldraxxus would call a corpsefly \"regal.\"\"\nCovenant:\nNecrolord\nVendor:\nSu Zettai\nZone:\nMaldraxxus\nCost:\n7500" }
entries[186489] = { ["name"] = "Lord of the Corpseflies", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"To be the Lord of the Corpseflies, you've got to lay a LOT of eggs.\"\nCovenant:\nNecrolord\nDrop:\nFleshwing\nZone:\nKorthia" }
entries[186490] = { ["name"] = "Battlefield Swarmer Harness", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Exalted with Death's Advance and the completion of the assault meta achievement \"On the Offensive.\"\n\n\"Corpseflies are strongly attracted to the smell of dead bodies and will swarm an active battlefield as soon as the first corpse falls.\"\nCovenant:\nNecrolord\nVendor:\nDuchess Mynx\nZone:\nKorthia\nCost:\n1000\nAchievement:\nOn the Offensive" }
entries[186491] = { ["name"] = "Spring Wilderling Harness", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding" }
entries[186492] = { ["name"] = "Summer Wilderling Harness", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Stubborn and rebellious, this wilderling is loyal to very few. But those few are bonded for life.\"\nCovenant:\nNight Fae\nDrop:\nEscaped Wilderling\nZone:\nKorthia" }
entries[186493] = { ["name"] = "Ardenweald Wilderling Harness", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"As anima flows to the distant wealds of Ardenweald once more, the wilderlings awaken and cautiously emerge from their canopy burrows.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[186494] = { ["name"] = "Autumnal Wilderling Harness", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown 70\n\n\"The wilderlings are benevolent, magical creatures of Ardenweald, and are drawn to souls that are strong and pure.\"\nCovenant:\nNight Fae\nVendor:\nElwyn\nZone:\nArdenweald\nCost:\n7500" }
entries[186495] = { ["name"] = "Winter Wilderling Harness", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Exalted with Death's Advance and the completion of the assault meta achievement \"On the Offensive.\"\n\n\"Wilderlings serve as support units in battle, preserving their allies and rendering enemy magics useless.\"\nCovenant:\nNight Fae\nVendor:\nDuchess Mynx\nZone:\nKorthia\nCost:\n1000\nAchievement:\nOn the Offensive" }
