entries[186565] = { ["name"] = "Memory of Rampant Transference", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nRampant Transference Runecarving Power Instant\nThe Strength gained from Death's Due is increased by 3% and persists for 2 sec longer. While standing within your Death's Due your Runic Power generation is increased by 20%.\nRunecarve on: Chest, Waist\nSource: Granted at Renown 48 with your covenant.\nRequires: Death Knight" }
entries[186566] = { ["name"] = "Memory of the Final Sentence", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFinal Sentence Runecarving Power Instant\nWhen Shackle the Unworthy is applied to an enemy, instantly gain a Rune and your damage is increased by 4%, stacking up to 20% for 15 sec.\nRunecarve on: Head, Shoulder, Back\nSource: Granted at Renown 48 with your covenant.\nRequires: Death Knight" }
entries[186567] = { ["name"] = "Memory of Insatiable Hunger", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nInsatiable Hunger Runecarving Power Instant\nWhen Swarming Mist ends it deals (86.42% of Attack Power) Shadow damage to 5 nearby enemies, healing you for 25% of the damage dealt. The damage is increased by 2% for every 1 Runic Power spent while Swarming Mist was active.\nRunecarve on: Legs, Feet\nSource: Granted at Renown 48 with your covenant.\nRequires: Death Knight" }
entries[186568] = { ["name"] = "Memory of an Abomination's Frenzy", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nAbomination's Frenzy Runecarving Power Instant\nAbomination Limb's duration is increased by 4 sec and the frequency it grants [ Blood : Bone Shield / Frost : Rime / Unholy : Runic Corruption ] is increased by 2 sec. The first time an enemy is damaged by Abomination Limb they take 20% increased damage from you for 12 sec. (20s cooldown)\nRunecarve on: Feet, Wrist, Hands\nSource: Granted at Renown 48 with your covenant.\nRequires: Death Knight" }
entries[186569] = { ["name"] = "Angry Needler Nest", ["text"] = "Quest Item\nUse: Throw the nest on a Herald, breaking its concentration and making it vulnerable to attack. (15 Sec Cooldown)" }
entries[186570] = { ["name"] = "Memory of Glory", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nGlory Runecarving Power Instant\nConqueror's Banner affects 1 additional ally and every [ Arms : 20 ] [ Fury : 25 /\n\nProtection\n10 ] Rage you spend while it is active increases the duration of your banner by 0.5 sec.\nRunecarve on: Chest, Waist\nSource: Granted at Renown 48 with your covenant.\nRequires: Warrior" }
entries[186572] = { ["name"] = "Memory of the Sinful Surge", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSinful Surge Runecarving Power Instant\nCondemn extends the duration of [ Arms : Colossus Smash by 1.5 sec ] [ Fury : Recklessness by 2.0 sec /\n\nProtection\nAvatar by 2.5 sec ] (500ms cooldown)\nRunecarve on: Head, Neck, Shoulder\nSource: Granted at Renown 48 with your covenant.\nRequires: Warrior" }
entries[186573] = { ["name"] = "Defense Map", ["text"] = "Binds when picked up\nDuration: 3 days (real time)\nThis Item Begins a Quest\n\"A map marking the location of all the magical defenses of Perdition Hold.\"" }
entries[186576] = { ["name"] = "Memory of Nature's Fury", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nNature's Fury Runecarving Power Instant\nAncient Aftershock's duration is increased by 3 sec and enemies hit take [(13.83% of Attack Power)o * 3] Nature damage over 6 sec, stacking 6 times.\nRunecarve on: Wrist, Hands, Back\nSource: Granted at Renown 48 with your covenant.\nRequires: Warrior" }
entries[186577] = { ["name"] = "Memory of the Unbridled Swarm", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nUnbridled Swarm Runecarving Power Instant\nAdaptive Swarm has a 60% chance to split into two Swarms each time it jumps.\nRunecarve on: Chest, Wrist\nSource: Granted at Renown 48 with your covenant." }
entries[186580] = { ["name"] = "A Tiny Sinstone", ["text"] = "Binds when picked up\nUnique\nUse: When summoned, Pepe will sometimes be dressed like a Venthyr." }
entries[186591] = { ["name"] = "Memory of the Harmonic Echo", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nHarmonic Echo Runecarving Power Instant\nDamage dealt to enemies affected by Radiant Spark's vulnerability echo to your current enemy target and 4 nearby enemies for 25% of the damage dealt.\nRunecarve on: Head, Waist, Back\nSource: Granted at Renown 48 with your covenant." }
entries[186593] = { ["name"] = "A Tiny Pair of Wings", ["text"] = "Binds when picked up\nUnique\nUse: When summoned, Pepe will sometimes be dressed like a Kyrian." }
entries[186598] = { ["name"] = "Recipe: Crafter's Mark III", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft an Optional Reagent that sets the required level to 60 and item level of the item to 200.\n\nUsable with Shadowlands recipes for Rare (blue) armor and accessories.\nRequires Death's Advance\n- Honored\n\"Teaches you how to craft a Crafter's Mark III.\"" }
entries[186599] = { ["name"] = "Stygian Ember", ["text"] = "Binds when picked up\n\"Once a brave warrior, now reduced to a lost sliver of undeath.\"\nSell Price:" }
