entries[186605] = { ["name"] = "Nilganihmaht's Runed Band", ["text"] = "Binds when picked up\n\"You dare flaunt your runes before the master of Domination?\"" }
entries[186606] = { ["name"] = "Nilganihmaht's Signet Ring", ["text"] = "Binds when picked up\n\"Braggart! This symbol of your failed reign means nothing here!\"" }
entries[186607] = { ["name"] = "Nilganihmaht's Silver Ring", ["text"] = "Binds when picked up\n\"Riches mean nothing in this realm of torment.\"" }
entries[186608] = { ["name"] = "Nilganihmaht's Gold Band", ["text"] = "Binds when picked up\n\"Such vanity, to claim a ring of gold!\"" }
entries[186609] = { ["name"] = "Memory of Sinful Indulgence", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSinful Indulgence Runecarving Power\nEach time Ravenous Frenzy is applied its duration is increased by 0.1 sec. Additionally, Ravenous Frenzy lingers and will not overcome you for 3 sec after it ends.\nRunecarve on: Waist, Hands\nSource: Granted at Renown 48 with your covenant." }
