entries[186615] = { ["name"] = "Mirror of the Conjured Twin", ["text"] = "Torghast, Tower of the Damned\nUse: Creates a copy of you nearby for 2 min, which casts unpredictable spells and attacks your enemies. (5 Min Cooldown)\n\"Your reflection grins ominously at you through a shadowy fog.\"" }
