entries[186621] = { ["name"] = "Memory of Death's Fathom", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDeath's Fathom Runecarving Power Instant\nApproximately 1.25 procs per minute\nYour Fireball, Frostbolt, and Arcane Blast have a chance to grant Deathborne for 8 sec. While in the form of a skeletal mage the spell damage granted is increased by 1% for each enemy hit by Fireball, Frostbolt, and Arcane Blast.\nRunecarve on: Shoulder, Feet, Wrist\nSource: Granted at Renown 48 with your covenant.\nRequires: Mage" }
