entries[186635] = { ["name"] = "Memory of Sinful Delight", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSinful Delight Runecarving Power Instant\nConsuming [ Arcane : Clearcast ] [ Fire : a Fire Blast charge /\n\nFrost\nBrain Freeze ] reduces Mirrors of Torment's cooldown by 4 sec. If Mirrors of Torment is dispelled the cooldown is reduced by 45 sec.\nRunecarve on: Legs, Feet\nSource: Granted at Renown 48 with your covenant.\nRequires: Mage" }
entries[186636] = { ["name"] = "Cage of Mawrats", ["text"] = "Torghast, Tower of the Damned\nUse: Releases a brood of mawrats that attack when commanded. (5 Min Cooldown)\n\"Several Mawrats gaze hopefully at you through the bars.\"" }
entries[186637] = { ["name"] = "Tazavesh Gearglider", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Brokers of all types use these gliders to travel around Tazavesh and similar nearby outposts, and carry their goods as well.\"\nAchievement:\nFake It 'Til You Make It\nCategory:\nShadowlands Dungeon" }
entries[186638] = { ["name"] = "Cartel Master's Gearglider", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Only the richest cartel leaders are able to afford the metals required to craft the Cartel Master's Gearglider.\"\nDrop:\nSo'leah\nZone:\nTazavesh, the Veiled Market" }
entries[186639] = { ["name"] = "Xy Trustee's Gearglider", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Cartel Xy trades in many currencies; none are as valuable to its inner circle as loyalty.\"\nSource:\n[REDACTED]" }
entries[186640] = { ["name"] = "Vandal's Gearglider", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A rarer, customized glider most commonly used for clandestine gatherings. Its silence makes it near impossible to detect, making it a favored tool for those who work in the shadows.\"\nFaction:\nManaforge Vandals\nRenown:\n8\nLocation:\nShadow Point" }
entries[186641] = { ["name"] = "Tamed Mauler Harness", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"When it comes to taming devourers, all it takes is a little anima and a lot of patience. And a lot of healing potions.\"\nDrop:\nSupplies of the Archivist's Codex\nZone:\nKorthia" }
entries[186642] = { ["name"] = "Vengeance's Reins", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Sylvanas lost a part of herself the day Arthas took her life, and the darkness within her grew to fill the void.\"\nDrop:\nLady Sylvanas Windrunner\nZone:\nSanctum of Domination\nDifficulty:\nMythic" }
entries[186643] = { ["name"] = "Reins of the Wanderer", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A curious and inquisitive doe, she doesn't mean to worry her master, she just gets distracted easily. Especially with all of the new things to see on Korthia.\"\nZone:\nKorthia" }
entries[186644] = { ["name"] = "Beryl Shardhide", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These shardhides find it easy to hide in the underbrush, and it is rare to find one that is tamed.\"\nDrop:\nDeath's Advance Supplies\nZone:\nKorthia" }
entries[186645] = { ["name"] = "Crimson Shardhide", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"When Korthia was pulled into The Maw, only a few hardy species survived.\"\nDrop:\nMalbog\nZone:\nKorthia" }
entries[186646] = { ["name"] = "Darkmaul", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"An older shardhide, Darkmaul was relatively tame and friendly around Korthians. He was thought lost to the calamity.\"\nZone:\nKorthia" }
entries[186647] = { ["name"] = "Amber Shardhide", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Death's Advance\n- Revered\n\n\"The bright colors of Korthian wildlife indicate that they have either few predators, or are tough enough to fight back.\"\nVendor:\nDuchess Mynx\nZone:\nKorthia\nFaction:\nDeath's Advance - Revered\nCost:\n5000" }
entries[186648] = { ["name"] = "Soaring Razorwing", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires The Archivists' Codex\n- Tier 6\n\n\"The hide of the razorwing is light, allowing it to fly, but also quite tough, allowing them to survive passage into the Maw.\"\nVendor:\nArchivist Roh-Suir\nZone:\nKorthia\nFaction:\nThe Archivists' Codex - Tier 6\nCost:\n5000" }
entries[186649] = { ["name"] = "Fierce Razorwing", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Razorwings generally stay away from other Korthian species, but with time and patience, they can be tamed as well.\"\nDrop:\nDeath's Advance Supplies\nZone:\nKorthia" }
entries[186650] = { ["name"] = "Death's Advance Supplies", ["text"] = "Binds to Warband\nUnique\n<Right Click to Open>\nSell Price:" }
entries[186651] = { ["name"] = "Dusklight Razorwing", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Razorwings can be seen throughout Korthia, making their nests on high hills and in trees.\"\nZone:\nKorthia" }
entries[186652] = { ["name"] = "Garnet Razorwing", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Korthia was once known for its bright red flowers. Several species were known for consuming or rolling in them, and taking on bright red coloration as a result.\"\nDrop:\nReliwik the Defiant\nZone:\nKorthia" }
entries[186653] = { ["name"] = "Bracer of Hrestimorak", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The treachery of Hrestimorak was infamous, betraying his people to claim power. Facing damnation in the Maw, he tried to subvert the Jailer... a foolish act that would earn him an eternity of torment.\"\nAchievement:\nGlory of the Dominant Raider\nZone:\nSanctum of Domination" }
entries[186654] = { ["name"] = "Bracelet of Salaranga", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Salaranga was the most cunning of her kin and hid amongst the Beastwarrens. She struck at the Banished One with a horde of bestial allies. It did not matter.\"\nAchievement:\nBreaking the Chains\nZone:\nKorthia and The Maw" }
entries[186655] = { ["name"] = "Mawsworn Charger's Reins", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The fate of all horse mounts.\"\nAchievement:\nFlawless Master\nZone:\nTorghast, Tower of the Damned" }
entries[186656] = { ["name"] = "Sanctum Gloomcharger's Reins", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Only the Jailer's most powerful lieutenants are gifted these steeds to stalk the halls of the Tower.\"\nDrop:\nThe Nine\nZone:\nSanctum of Domination" }
entries[186657] = { ["name"] = "Soulbound Gloomcharger's Reins", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Ve'nari has many methods of sneaking around the Maw and disrupting the Jailer's plans, including binding his own minions.\"\nDrop:\nMysterious Gift from Ve'nari\nZone:\nThe Maw" }
entries[186659] = { ["name"] = "Fallen Charger's Reins", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The charger's screams echo across the Maw as it continues a never-ending ride across the land, forever looking for escape from the endless torments it has been forced to endure.\"\nDrop:\nFallen Charger\nZone:\nThe Maw" }
