entries[186671] = { ["name"] = "Vantus Rune Technique: Sanctum of Domination", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Vantus Rune: Sanctum of Domination.\nRequires Shadowlands Inscription (100)\nSell Price:\nVantus Rune: Sanctum of Domination\nUse: Attune yourself to the energies of the targeted Sanctum of Domination raid boss, increasing your Versatility by 1875 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Luminous Ink (10), Umbral Ink (10), Tranquil Ink , Dark Parchment" }
entries[186672] = { ["name"] = "Ephemeral Wings", ["text"] = "Quest Item\nUnique\nUse: Leap forward on ephemeral wings, reducing fall speed for 10 sec. Then jump to a nearby location. (6 Sec Cooldown)" }
entries[186673] = { ["name"] = "Memory of Kindred Affinity", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nKindred Affinity Level 80 Runecarving Power Instant\nYou and your Kindred Spirit each gain a bonus secondary stat based on their Covenant. This bonus is halved for your Kindred Spirit, however both bonuses are doubled while the bond is Empowered.\n\nKyrian : Mastery increased by 571 .\nNight Fae : Haste increased by 6%.\nVenthyr : Critical Strike chance increased by 6%.\nNecrolord : Versatility increased by 6%.\nRunecarve on: Neck, Shoulder\nSource: Granted at Renown 48 with your covenant.\nRequires: Druid" }
entries[186676] = { ["name"] = "Memory of the Toxic Onslaught", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nToxic Onslaught Runecarving Power Instant\nWhen Sepsis expires on your target [ Assassination : you gain Adrenaline Rush and Shadow Blades ] [ Outlaw : you gain Shadow Blades and apply Vendetta to your current target ] [ Subtlety : you gain Adrenaline Rush and apply Vendetta to your current target ] for 10 sec.\nRunecarve on: Chest, Legs, Feet\nSource: Granted at Renown 48 with your covenant.\nRequires: Rogue" }
entries[186677] = { ["name"] = "Metallic Socket", ["text"] = "Sell Price:" }
entries[186678] = { ["name"] = "Mawforged Weapons Cache", ["text"] = "Torghast, Tower of the Damned\nUse: Mawforged Weapons aid you in combat for 2 min. (5 Min Cooldown)\n\"These weapons seem to have a life of their own.\"" }
entries[186679] = { ["name"] = "Scroll of Domination", ["text"] = "Torghast, Tower of the Damned\nUse: Places a non-elite enemy target under your control for 2 min. When the rune fades, the controlled target explodes dealing damage to everyone nearby. (5 Min Cooldown)\n\"Don't stare at the runes too long.\"" }
entries[186680] = { ["name"] = "Gold Filled Boot", ["text"] = "Binds when picked up\n\"Don't forget it is full of gold, otherwise it may result in toe injury.\"\n<Right Click to Open>" }
entries[186684] = { ["name"] = "Memories of Brighter Times", ["text"] = "Use: Recall brighter times in Oribos, before the Maw grew in power. Lasts 168 hrs.\n\"Does nothing to affect the coming darkness, but makes it look nicer.\"\nSell Price:" }
entries[186685] = { ["name"] = "Relic Fragment", ["text"] = "Korthian Relics\nBinds when picked up\nUse: Submit the Relic Fragments to Archivist Roh-Suir in the Reliquary of Remembrance, generating 1 Cataloged Research.\n\"Ancient symbols still show on the surface of these fragments.\"\nSell Price:" }
entries[186686] = { ["name"] = "Pallid Oracle Bones", ["text"] = "Binds when used\nToy\nUse: Consult the bones to learn your future. (15 Min Cooldown)\n\"A set of small bones with symbols carved into them that allow the user to learn about their future.\"" }
entries[186687] = { ["name"] = "Memory of Celestial Spirits", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCelestial Spirits Runecarving Power Instant\nConvoke the Spirits' cooldown is reduced by 50% and its duration is reduced by 25%. Convoke the Spirits has an increased chance to use an exceptional spell or ability.\nRunecarve on: Legs, Feet\nSource: Granted at Renown 48 with your covenant.\nRequires: Druid" }
entries[186688] = { ["name"] = "Gold Filled Wash Bucket", ["text"] = "Binds when picked up\n\"The handle really makes it easy to move around the gold held within.\"\n<Right Click to Open>\nSell Price:" }
entries[186689] = { ["name"] = "Memory of the Splintered Elements", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSplintered Elements Runecarving Power Instant\nEach additional Lightning Bolt generated by Primordial Wave increases your Haste by 10% for 12 sec.\nRunecarve on: Neck, Waist\nSource: Granted at Renown 48 with your covenant." }
entries[186690] = { ["name"] = "Gold Filled Barrel", ["text"] = "Binds when picked up\n\"Rendle was pretty upset when he had to use his brew barrel for holding gold.\"\n<Right Click to Open>\nSell Price:" }
entries[186691] = { ["name"] = "Gold Filled Satchel", ["text"] = "Binds when picked up\n\"Extra stitching was used to make the satchels able to hold all the coins.\"\n<Right Click to Open>\nSell Price:" }
entries[186692] = { ["name"] = "Gold Filled Helmet", ["text"] = "Binds when picked up\n\"Instructions note to hold upside down until ready to take out coins.\"\n<Right Click to Open>\nSell Price:" }
entries[186693] = { ["name"] = "Gold Filled Wheelbarrow", ["text"] = "Binds when picked up\n\"When you need a wheelbarrow to hold all your gold do you have enough?\"\n<Right Click to Open>\nSell Price:" }
entries[186694] = { ["name"] = "Shaded Bag of Ore", ["text"] = "Binds when picked up\n\"A bag of ore from the Shadowlands.\"\n<Right Click to Open>" }
entries[186695] = { ["name"] = "Lovely Pet Bandage", ["text"] = "Quest Item\nUse: Gets an injured friend back on their feet (so to speak)." }
entries[186696] = { ["name"] = "Ta Coin of Favors", ["text"] = "Quest Item\n\"A symbolic coin that recognizes the completion of a favor for a favor.\"" }
entries[186697] = { ["name"] = "Blossom Burst", ["text"] = "Use: Douse your friends with a burst of green color! Fun for all ages! (3 Min Cooldown)\n5 Charges" }
entries[186698] = { ["name"] = "Torch Burst", ["text"] = "Use: Douse your friends with a burst of orange color! Fun for all ages! (3 Min Cooldown)\n5 Charges" }
entries[186699] = { ["name"] = "Widow Burst", ["text"] = "Use: Douse your friends with a burst of purple color! Fun for all ages! (3 Min Cooldown)\n5 Charges" }
entries[186700] = { ["name"] = "Marrow Burst", ["text"] = "Use: Douse your friends with a burst of gray color! Fun for all ages! (3 Min Cooldown)\n5 Charges" }
entries[186701] = { ["name"] = "Glory Burst", ["text"] = "Use: Douse your friends with a burst of yellow color! Fun for all ages! (3 Min Cooldown)\n5 Charges" }
entries[186702] = { ["name"] = "Pallid Bone Flute", ["text"] = "Toy\nUse: Play a haunting melody, inspiring those around you to dance. (10 Min Cooldown)\n\"A bone flute from the land of the dead? Doesn't seem ominous at all.\"" }
entries[186703] = { ["name"] = "Gold Chalice", ["text"] = "Binds when picked up\n\"The cup itself looks to be worth a lot of gold alone.\"\nSell Price:" }
entries[186704] = { ["name"] = "Twilight Tea", ["text"] = "Use: Restores ( 30000 / 5 * 20) mana over 20 sec. Must remain seated while drinking." }
entries[186705] = { ["name"] = "Gold Filled Chalice", ["text"] = "Binds when picked up\n\"Rendle scooped out a heaping pile of coins from his enormous cache to fill the cup.\"\n<Right Click to Open>" }
entries[186706] = { ["name"] = "Gold Filled Hat", ["text"] = "Binds when picked up\n\"The threads of the hat are straining under the weight of all the coins it is holding.\"\n<Right Click to Open>\nSell Price:" }
entries[186707] = { ["name"] = "Gold Filled Crate", ["text"] = "Binds when picked up\n\"The crate is so full of coins that they are slipping out between the lid.\"\n<Right Click to Open>\nSell Price:" }
entries[186708] = { ["name"] = "Gold Filled Paint Brush Cup", ["text"] = "Binds when picked up\n\"No one usually questions the odd interests of a dredger, especialy one that provides such a crucial service as gear repair.\"\n<Right Click to Open>\nSell Price:" }
entries[186710] = { ["name"] = "Memory of the Obedient", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nObedience Runecarving Power Instant\nFlagellation now also increases your Versatility by 0.5%. Each combo point spent while Flagellation is active decreases it's cooldown by 1 sec. (100ms cooldown)\nRunecarve on: Head, Back\nSource: Granted at Renown 48 with your covenant.\nRequires: Rogue" }
entries[186712] = { ["name"] = "Memory of the Deathspike", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDeathspike Runecarving Power Instant\nSerrated Bone Spike has 2 additional charges and launches 1 additional bone spike at nearby enemies.\nRunecarve on: Wrist, Hands\nSource: Granted at Renown 48 with your covenant.\nRequires: Rogue" }
entries[186713] = { ["name"] = "Nilganihmaht Control Ring", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Of all the giants who dared defy the Jailer, Nilganihmaht was the most arrogant. For this transgression, the giant's severed hand was hidden within a veil of torments, and the rings that could summon it back were scattered across the Maw.\"\nZone:\nThe Maw" }
entries[186714] = { ["name"] = "Research Report: All-Seeing Crystal", ["text"] = "Binds when picked up\nUnique\nUse: Allows you to permanently see and find creatures who are carrying Relic Fragments.\nRequires Tier 2 research level with The Archivists' Codex.\n\"Roh-Suir was able to recreate the research on an All-Seeing Crystal, allowing you to affix one to the Lodestaff to detect other relics.\"" }
entries[186715] = { ["name"] = "Research Report: Improved Alloys", ["text"] = "Binds when picked up\nUnique\nUse: Allows you to upgrade your items from Korthia and the Maw to Rank 10.\n\"Analyzing the effects of domination magic on the items of Korthia and the Maw have lead to improved alloys that can allow us to make our items hardier and more powerful.\"" }
entries[186716] = { ["name"] = "Research Report: Ancient Shrines", ["text"] = "Binds when picked up\nUnique\nUse: Allows you to interact with the swords near ancient shrines granting you the ability to reach inaccessible relic treasures.\nRequires Tier 5 research level with The Archivists' Codex.\n\"Further research into the mysterious Cipher of Understanding you recovered from the rift has allowed us to understand the interaction with the ancient shrine swords found around Korthia.\"" }
entries[186717] = { ["name"] = "Research Report: Adaptive Alloys", ["text"] = "Binds when picked up\nUnique\nUse: Allows you to upgrade your items from Korthia and the Maw to Rank 5.\nRequires Tier 6 research level with The Archivists' Codex and Renown 61 or higher.\n\"Further research from the relic recovery have led us to discover new adaptive alloys that will further allow us to increase the power of items touched by domination magic in Korthia and the Maw.\"" }
entries[186718] = { ["name"] = "Teleporter Repair Kit", ["text"] = "Binds when picked up\nRequires Tier 3 research level with The Archivists' Codex.\n\"One thing remains universal: righty tighty, lefty loosey. Required to repair Ancient Teleporters around Korthia, allowing access to hidden vaults.\"" }
entries[186721] = { ["name"] = "Treatise: Relics Abound in the Shadowlands", ["text"] = "Binds when picked up\nUnique\nUse: Permanently grants you the ability to find relics that grant bonus reputation with the Shadowlands zone factions when completing World and Daily Quests, looting treasures, and defeating rare creatures in their realms.\nRequires Tier 6 research level with The Archivists' Codex." }
entries[186722] = { ["name"] = "Treatise: The Study of Anima and Harnessing Every Drop", ["text"] = "Binds when picked up\nUnique\nUse: Permanently grants you the ability to find 25 extra Anima when completing World and Daily Quests, looting treasures, or killing rare creatures in the Shadowlands.\nRequires Tier 5 research level with The Archivists' Codex." }
entries[186724] = { ["name"] = "Technique: Contract: Death's Advance", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Contract: Death's Advance.\nRequires Shadowlands Inscription (60)\nRequires Death's Advance\n- Revered\nSell Price:\nContract: Death's Advance\nUse: Enter a contract with the Death's Advance that allows you to gain reputation with them every time you complete a world quest in the Shadowlands.\nRequires Death's Advance\n- Friendly\nRequires Luminous Ink , Umbral Ink , Dark Parchment" }
entries[186725] = { ["name"] = "Bonemeal Bread", ["text"] = "Use: Restores ( 22500 / 5 * 20) health over 20 sec. Must remain seated while eating." }
entries[186726] = { ["name"] = "Porous Rock Candy", ["text"] = "Use: Enjoy a tasty treat.\n\"Contains no nutritional value.\"" }
