entries[186731] = { ["name"] = "Repaired Riftkey", ["text"] = "Binds when picked up\nEquip: Allows you to enter a Rift Portal in Korthia and stay within for 15 min.\nRequires Tier 4 research level with The Archivists' Codex.\n\"This stone shakes in your hand, humming with strange power and whispers from the beyond.\"\nSell Price:" }
